public void insert()
{
    next insert();

    TAMRebateTrans  rebateTrans;
    TAMRebateDeal   rebateDeal;
    TAMRebateDateTrans  rebateDateTrans;
    METTierRateTrans    tierRateTrans;
    METTierRebateTrans  tierRebateTrans;

    select firstonly rebateDateTrans
        where rebateDateTrans.RebateId == this.RebateId;

    select firstonly rebateDeal
        where rebateDeal.RecId == rebateDateTrans.RebateDeal;

    if (rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate
          && rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        select firstonly tierRateTrans
        where tierRateTrans.RebateId == this.RebateId
        && tierRateTrans.FromDate <= this.RebateRefDate
        && tierRateTrans.ToDate >= this.RebateRefDate
        && tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate;

        if (tierRateTrans.RecId)
        {
            this.RebateAmount = (this.RebateRefAmount * tierRateTrans.EligibleRebate)/100;
        }           
    }
    else if (rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Provision
               && rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        select firstonly tierRateTrans
        where tierRateTrans.RebateId == this.RebateId
        && tierRateTrans.FromDate <= this.RebateRefDate
        && tierRateTrans.ToDate >= this.RebateRefDate
        && tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Provision;

        this.RebateAmount = (this.RebateRefAmount * tierRateTrans.EligibleRebate)/100;
    }
}
